import '../../../core/network/api_client.dart';import 'notification_models.dart';class NotificationRepository{NotificationRepository(this._client);final ApiClient _client;Future<List<AppNotification>> get()async{final r=await _client.dio.get<List<dynamic>>('/api/notifications');return r.data!.map((e)=>AppNotification.fromJson(e)).toList();}Future<void>read(String id)=>_client.dio.post<void>('/api/notifications/'+id+'/read');Future<void>readAll()=>_client.dio.post<void>('/api/notifications/read-all');}